import{_ as t,a as W,b as e,c as B,d as I,e as i,f as M,g as N,h as a,i as o,j as s,k as d,l as n,m as l,n as h,o as g,p as u,q as c,r as m,s as b,t as p,u as q,v as x,w as f,x as y,y as v,z as k,A as C,B as w,C as P,D as _}from"./chunks/mansion.Bp8AyT7f.js";import{_ as S}from"./chunks/bettys-market.BtcIJoBn.js";import{_ as H,o as T,c as A,a2 as D}from"./chunks/framework.YbKlqpdh.js";const K=JSON.parse('{"title":"Bâtiments","description":"Construire, placer et déplacer les bâtiments — coûts, niveau et temps.","frontmatter":{"title":"Bâtiments","description":"Construire, placer et déplacer les bâtiments — coûts, niveau et temps."},"headers":[],"relativePath":"fr/buildings/index.md","filePath":"fr/buildings/index.md","lastUpdated":1788424452000}'),z={name:"fr/buildings/index.md"};function G(V,r,F,U,j,R){return T(),A("div",null,[...r[0]||(r[0]=[D('<h1 id="batiments" tabindex="-1">Bâtiments <a class="header-anchor" href="#batiments" aria-label="Permalink to &quot;Bâtiments&quot;">​</a></h1><p>Les bâtiments débloquent la cuisine, les animaux, le compost, la serre, etc. Cette page liste tous les bâtiments du jeu avec leurs coûts.</p><h2 id="pour-commencer" tabindex="-1">Pour commencer <a class="header-anchor" href="#pour-commencer" aria-label="Permalink to &quot;Pour commencer&quot;">​</a></h2><h3 id="construire-un-batiment" tabindex="-1">Construire un bâtiment <a class="header-anchor" href="#construire-un-batiment" aria-label="Permalink to &quot;Construire un bâtiment&quot;">​</a></h3><ol><li>Cliquez sur l’<strong>Établi</strong> (Workbench) <img class="item-icon" src="'+t+'" alt="Workbench" width="40" height="40"> sur votre ferme.</li><li>Ouvrez l’onglet <strong>Build</strong> pour voir la liste des bâtiments disponibles selon votre niveau.</li><li>Payez les <strong>coins</strong><img class="item-icon" src="'+W+'" alt="Coins" width="24" height="24"> et les <strong>ressources</strong> demandées. Le bâtiment part dans votre inventaire / coffre.</li></ol><h3 id="placer-un-batiment" tabindex="-1">Placer un bâtiment <a class="header-anchor" href="#placer-un-batiment" aria-label="Permalink to &quot;Placer un bâtiment&quot;">​</a></h3><ol><li>Cliquez sur le <strong>marteau</strong><img class="item-icon" src="'+e+'" alt="Mode aménagement" width="24" height="24"> en bas de l’écran pour entrer en <strong>mode aménagement</strong> (landscaping).</li><li>Ouvrez le <strong>coffre</strong><img class="item-icon" src="'+B+'" alt="Coffre" width="24" height="24"> (ou le panneau rapide) et choisissez la catégorie <strong>bâtiments</strong><img class="item-icon" src="'+I+'" alt="Bâtiments" width="24" height="24">.</li><li>Sélectionnez le bâtiment, placez-le sur un emplacement libre, puis validez avec <img class="item-icon" src="'+i+'" alt="Confirmer" width="24" height="24"> (ou annulez avec <img class="item-icon" src="'+M+'" alt="Annuler" width="24" height="24"> ).</li></ol><h3 id="deplacer-un-batiment" tabindex="-1">Déplacer un bâtiment <a class="header-anchor" href="#deplacer-un-batiment" aria-label="Permalink to &quot;Déplacer un bâtiment&quot;">​</a></h3><ol><li>Entrez en <strong>mode aménagement</strong> avec le <strong>marteau</strong><img class="item-icon" src="'+e+'" alt="Mode aménagement" width="24" height="24">.</li><li>Cliquez sur le bâtiment déjà posé, puis <strong>glissez-le</strong><img class="item-icon" src="'+N+'" alt="Déplacer" width="24" height="24"> vers le nouvel emplacement.</li><li>Validez le placement avec <img class="item-icon" src="'+i+'" alt="Confirmer" width="24" height="24">.</li></ol><h3 id="ameliorer-upgrade-un-batiment" tabindex="-1">Améliorer (upgrade) un bâtiment <a class="header-anchor" href="#ameliorer-upgrade-un-batiment" aria-label="Permalink to &quot;Améliorer (upgrade) un bâtiment&quot;">​</a></h3><p>Certains bâtiments ont <strong>plusieurs niveaux</strong> (Hen House, Barn, Water Well, Pet House, Aging Shed) :</p><ol><li>Cliquez sur le bâtiment déjà placé.</li><li>Ouvrez l’option <strong>Upgrade</strong><img class="item-icon" src="'+e+'" alt="Upgrade" width="24" height="24"> si elle est disponible.</li><li>Payez les <strong>coins</strong> et ressources du niveau suivant (détails dans chaque fiche ci-dessous).</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Certains bâtiments de base (Marché de Betty, Town Center…) sont déjà sur la ferme. D’autres demandent le niveau bumpkin indiqué ci-dessous, ou une île précise (ex. Desert pour la Serre).</p><p><strong>Habitations</strong> (Town Center → House → Manor → Mansion) : <strong>non craftables</strong>. Elles sont <strong>fournies / remplacées</strong> quand vous changez d’île.</p><p><strong>Apparence (skins)</strong> : beaucoup de bâtiments changent de look selon l’<strong>île / biome</strong> et parfois la <strong>saison</strong>. Ce n’est qu’esthétique (sauf pour les habitations, où le bâtiment lui-même change).</p></div><h2 id="index" tabindex="-1">Index <a class="header-anchor" href="#index" aria-label="Permalink to &quot;Index&quot;">​</a></h2><ul class="building-index"><li><a href="#market"><img class="item-icon" src="'+S+'" alt="" width="28" height="28">Market</a></li><li><a href="#fire-pit"><img class="item-icon" src="'+a+'" alt="" width="28" height="28">Fire Pit</a></li><li><a href="#workbench"><img class="item-icon" src="'+t+'" alt="" width="28" height="28">Workbench</a></li><li><a href="#water-well"><img class="item-icon" src="'+o+'" alt="" width="28" height="28">Water Well</a></li><li><a href="#kitchen"><img class="item-icon" src="'+s+'" alt="" width="28" height="28">Kitchen</a></li><li><a href="#crafting-box"><img class="item-icon" src="'+d+'" alt="" width="28" height="28">Crafting Box</a></li><li><a href="#hen-house"><img class="item-icon" src="'+n+'" alt="" width="28" height="28">Hen House</a></li><li><a href="#compost-bin"><img class="item-icon" src="'+l+'" alt="" width="28" height="28">Compost Bin</a></li><li><a href="#turbo-composter"><img class="item-icon" src="'+h+'" alt="" width="28" height="28">Turbo Composter</a></li><li><a href="#premium-composter"><img class="item-icon" src="'+g+'" alt="" width="28" height="28">Premium Composter</a></li><li><a href="#bakery"><img class="item-icon" src="'+u+'" alt="" width="28" height="28">Bakery</a></li><li><a href="#fish-market"><img class="item-icon" src="'+c+'" alt="" width="28" height="28">Fish Market</a></li><li><a href="#deli"><img class="item-icon" src="'+m+'" alt="" width="28" height="28">Deli</a></li><li><a href="#warehouse"><img class="item-icon" src="'+b+'" alt="" width="28" height="28">Warehouse</a></li><li><a href="#aging-shed"><img class="item-icon" src="'+p+'" alt="" width="28" height="28">Aging Shed</a></li><li><a href="#smoothie-shack"><img class="item-icon" src="'+q+'" alt="" width="28" height="28">Smoothie Shack</a></li><li><a href="#toolshed"><img class="item-icon" src="'+x+'" alt="" width="28" height="28">Toolshed</a></li><li><a href="#barn"><img class="item-icon" src="'+f+'" alt="" width="28" height="28">Barn</a></li><li><a href="#crop-machine"><img class="item-icon" src="'+y+'" alt="" width="28" height="28">Crop Machine</a></li><li><a href="#greenhouse"><img class="item-icon" src="'+v+'" alt="" width="28" height="28">Greenhouse</a></li><li><a href="#pet-house"><img class="item-icon" src="'+k+'" alt="" width="28" height="28">Pet House</a></li><li><a href="#town-center"><img class="item-icon" src="'+C+'" alt="" width="28" height="28">Town Center</a></li><li><a href="#house"><img class="item-icon" src="'+w+'" alt="" width="28" height="28">House</a></li><li><a href="#manor"><img class="item-icon" src="'+P+'" alt="" width="28" height="28">Manor</a></li><li><a href="#mansion"><img class="item-icon" src="'+_+'" alt="" width="28" height="28">Mansion</a></li></ul><h2 id="liste-des-batiments" tabindex="-1">Liste des bâtiments <a class="header-anchor" href="#liste-des-batiments" aria-label="Permalink to &quot;Liste des bâtiments&quot;">​</a></h2><div class="building-card" id="market"><h3 id="market" tabindex="-1"><img class="building-hero" src="'+S+'" alt="Market"> Market <a class="header-anchor" href="#market" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/bettys-market.png&quot; alt=&quot;Market&quot; /&gt; Market&quot;">​</a></h3><p>Le <strong>Marché de Betty</strong> : acheter des graines et revendre des cultures contre des <strong>coins</strong>. Voir <a href="/sunflowerland-wiki/fr/crops/">Cultures</a>.</p><p><strong>Skin</strong> : change selon l’<strong>île</strong> (Basic / Desert / Volcano…) et la <strong>saison</strong>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>— (déjà sur la ferme)</td></tr><tr><td>Coins</td><td>0</td></tr><tr><td>Construction</td><td>30 s</td></tr><tr><td>Ingrédients</td><td>—</td></tr></tbody></table></div><div class="building-card" id="fire-pit"><h3 id="fire-pit" tabindex="-1"><img class="building-hero" src="'+a+'" alt="Fire Pit"> Fire Pit <a class="header-anchor" href="#fire-pit" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/fire-pit.png&quot; alt=&quot;Fire Pit&quot; /&gt; Fire Pit&quot;">​</a></h3><p>Premier bâtiment de <strong>cuisine</strong> (recettes simples). Voir <a href="/sunflowerland-wiki/fr/cooking/">Cuisine</a>.</p><p><strong>Skin</strong> : change selon l’<strong>île</strong> et la <strong>saison</strong>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>—</td></tr><tr><td>Coins</td><td>0</td></tr><tr><td>Construction</td><td>Instantané</td></tr><tr><td>Ingrédients</td><td>Wood ×3, Stone ×2</td></tr></tbody></table></div><div class="building-card" id="workbench"><h3 id="workbench" tabindex="-1"><img class="building-hero" src="'+t+'" alt="Workbench"> Workbench <a class="header-anchor" href="#workbench" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/workbench.png&quot; alt=&quot;Workbench&quot; /&gt; Workbench&quot;">​</a></h3><p><strong>Établi</strong> : outils, boosts, et l’onglet <strong>Build</strong> pour craft les autres bâtiments.</p><p><strong>Skin</strong> : change selon l’<strong>île</strong> (Basic / Desert / Volcano…).</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>—</td></tr><tr><td>Coins</td><td>5</td></tr><tr><td>Construction</td><td>1 min</td></tr><tr><td>Ingrédients</td><td>—</td></tr></tbody></table></div><div class="building-card" id="water-well"><h3 id="water-well" tabindex="-1"><img class="building-hero" src="'+o+'" alt="Water Well"> Water Well <a class="header-anchor" href="#water-well" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/water-well.png&quot; alt=&quot;Water Well&quot; /&gt; Water Well&quot;">​</a></h3><p>Augmente le nombre de <strong>parcelles fertiles</strong> (trous de culture utilisables). <strong>4 niveaux</strong> d’upgrade.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau pour craft</td><td>2</td></tr><tr><td>Coins (craft)</td><td>100</td></tr><tr><td>Construction</td><td>5 min</td></tr><tr><td>Ingrédients (craft)</td><td>Wood ×5</td></tr></tbody></table><h4 id="upgrades" tabindex="-1">Upgrades <a class="header-anchor" href="#upgrades" aria-label="Permalink to &quot;Upgrades&quot;">​</a></h4><p>Le puits doit être <strong>placé</strong> sur la ferme pour compter. Sans puits : <strong>17</strong> plots (île Basic) ou <strong>18</strong> (autres îles). Chaque niveau ajoute <strong>+8</strong> plots ; au niveau <strong>4</strong>, toutes les parcelles sont fertiles (99).</p><table tabindex="0"><thead><tr><th style="text-align:right;">Niveau</th><th style="text-align:right;">Coût coins</th><th>Ingrédients</th><th style="text-align:right;">Niveau bumpkin</th><th>Temps upgrade</th><th style="text-align:right;">Plots fertiles (Basic)</th><th style="text-align:right;">Plots fertiles (autres îles)</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:right;">— (base / craft)</td><td>Wood ×5 (craft)</td><td style="text-align:right;">2</td><td>—</td><td style="text-align:right;">25</td><td style="text-align:right;">26</td></tr><tr><td style="text-align:right;">2</td><td style="text-align:right;">200</td><td>Wood ×5, Stone ×2</td><td style="text-align:right;">4</td><td>1 h</td><td style="text-align:right;">33</td><td style="text-align:right;">34</td></tr><tr><td style="text-align:right;">3</td><td style="text-align:right;">400</td><td>Wood ×5, Stone ×5</td><td style="text-align:right;">11</td><td>2 h</td><td style="text-align:right;">41</td><td style="text-align:right;">42</td></tr><tr><td style="text-align:right;">4</td><td style="text-align:right;">800</td><td>Wood ×10, Stone ×10</td><td style="text-align:right;">15</td><td>4 h</td><td style="text-align:right;">Toutes</td><td style="text-align:right;">Toutes</td></tr></tbody></table></div><div class="building-card" id="kitchen"><h3 id="kitchen" tabindex="-1"><img class="building-hero" src="'+s+'" alt="Kitchen"> Kitchen <a class="header-anchor" href="#kitchen" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/kitchen.png&quot; alt=&quot;Kitchen&quot; /&gt; Kitchen&quot;">​</a></h3><p>Cuisine intermédiaire — plus de recettes que le Fire Pit.</p><p><strong>Skin</strong> : change selon l’<strong>île</strong> et la <strong>saison</strong>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>5</td></tr><tr><td>Coins</td><td>10</td></tr><tr><td>Construction</td><td>30 min</td></tr><tr><td>Ingrédients</td><td>Wood ×30, Stone ×5</td></tr></tbody></table></div><div class="building-card" id="crafting-box"><h3 id="crafting-box" tabindex="-1"><img class="building-hero" src="'+d+'" alt="Crafting Box"> Crafting Box <a class="header-anchor" href="#crafting-box" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/crafting-box.png&quot; alt=&quot;Crafting Box&quot; /&gt; Crafting Box&quot;">​</a></h3><p>Atelier pour <strong>crafter</strong> certains objets (matériaux de craft).</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>6</td></tr><tr><td>Coins</td><td>0</td></tr><tr><td>Construction</td><td>1 h</td></tr><tr><td>Ingrédients</td><td>Wood ×100, Stone ×5</td></tr></tbody></table></div><div class="building-card" id="hen-house"><h3 id="hen-house" tabindex="-1"><img class="building-hero" src="'+n+'" alt="Hen House"> Hen House <a class="header-anchor" href="#hen-house" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/hen-house.png&quot; alt=&quot;Hen House&quot; /&gt; Hen House&quot;">​</a></h3><p>Élever des <strong>poules</strong>. Voir <a href="/sunflowerland-wiki/fr/animals/">Animaux</a>. <strong>3 niveaux</strong>.</p><p><strong>Skin</strong> : change selon la <strong>saison</strong> (et le niveau d’upgrade).</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau pour craft</td><td>6</td></tr><tr><td>Coins (craft)</td><td>100</td></tr><tr><td>Construction</td><td>2 h</td></tr><tr><td>Ingrédients (craft)</td><td>Wood ×30, Iron ×5, Gold ×5</td></tr></tbody></table><h4 id="upgrades-1" tabindex="-1">Upgrades <a class="header-anchor" href="#upgrades-1" aria-label="Permalink to &quot;Upgrades&quot;">​</a></h4><p>Capacité de base : <strong>10 + 5 × (niveau − 1)</strong>. Avec <strong>Chicken Coop</strong> : +5 poules <strong>par niveau</strong> du Hen House.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Niveau</th><th style="text-align:right;">Coût coins</th><th>Ingrédients</th><th style="text-align:right;">Poules (base)</th><th style="text-align:right;">Poules (+ Chicken Coop)</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:right;">— (base)</td><td>—</td><td style="text-align:right;">10</td><td style="text-align:right;">15</td></tr><tr><td style="text-align:right;">2</td><td style="text-align:right;">7 500</td><td>Wood ×500, Iron ×50, Gold ×40, Crimstone ×10</td><td style="text-align:right;">15</td><td style="text-align:right;">25</td></tr><tr><td style="text-align:right;">3</td><td style="text-align:right;">50 000</td><td>Wood ×2500, Iron ×150, Gold ×100, Crimstone ×50, Oil ×100</td><td style="text-align:right;">20</td><td style="text-align:right;">35</td></tr></tbody></table></div><h2 id="composteurs" tabindex="-1">Composteurs <a class="header-anchor" href="#composteurs" aria-label="Permalink to &quot;Composteurs&quot;">​</a></h2><p>Les composteurs transforment des cultures (selon la saison) en compost + vers. Voir aussi <a href="/sunflowerland-wiki/fr/compost/">Compost</a>.</p><div class="building-card" id="compost-bin"><h3 id="compost-bin" tabindex="-1"><img class="building-hero" src="'+l+'" alt="Compost Bin"> Compost Bin <a class="header-anchor" href="#compost-bin" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/compost-bin.png&quot; alt=&quot;Compost Bin&quot; /&gt; Compost Bin&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>7</td></tr><tr><td>Coins</td><td>0</td></tr><tr><td>Construction</td><td>1 h</td></tr><tr><td>Ingrédients</td><td>Wood ×5, Stone ×5</td></tr><tr><td>Temps de cycle</td><td>6 h</td></tr><tr><td>Produit</td><td><strong>Sprout Mix</strong> ×10 — +0,2 rendement culture / parcelle</td></tr><tr><td>Vers</td><td><strong>Earthworm</strong></td></tr></tbody></table></div><div class="building-card" id="turbo-composter"><h3 id="turbo-composter" tabindex="-1"><img class="building-hero" src="'+h+'" alt="Turbo Composter"> Turbo Composter <a class="header-anchor" href="#turbo-composter" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/turbo-composter.png&quot; alt=&quot;Turbo Composter&quot; /&gt; Turbo Composter&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>12</td></tr><tr><td>Coins</td><td>0</td></tr><tr><td>Construction</td><td>2 h</td></tr><tr><td>Ingrédients</td><td>Wood ×50, Stone ×25</td></tr><tr><td>Temps de cycle</td><td>8 h</td></tr><tr><td>Produit</td><td><strong>Fruitful Blend</strong> ×3 — +0,1 rendement fruit / parcelle fruit</td></tr><tr><td>Vers</td><td><strong>Grub</strong></td></tr></tbody></table></div><div class="building-card" id="premium-composter"><h3 id="premium-composter" tabindex="-1"><img class="building-hero" src="'+g+'" alt="Premium Composter"> Premium Composter <a class="header-anchor" href="#premium-composter" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/premium-composter.png&quot; alt=&quot;Premium Composter&quot; /&gt; Premium Composter&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>18</td></tr><tr><td>Coins</td><td>0</td></tr><tr><td>Construction</td><td>4 h</td></tr><tr><td>Ingrédients</td><td>Gold ×50</td></tr><tr><td>Temps de cycle</td><td>12 h</td></tr><tr><td>Produit</td><td><strong>Rapid Root</strong> ×10 — −50 % temps de pousse des cultures (parcelles)</td></tr><tr><td>Vers</td><td><strong>Red Wiggler</strong></td></tr></tbody></table></div><div class="building-card" id="bakery"><h3 id="bakery" tabindex="-1"><img class="building-hero" src="'+u+'" alt="Bakery"> Bakery <a class="header-anchor" href="#bakery" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/bakery.png&quot; alt=&quot;Bakery&quot; /&gt; Bakery&quot;">​</a></h3><p>Pâtisserie / gâteaux et recettes avancées.</p><p><strong>Skin</strong> : change selon la <strong>saison</strong>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>8</td></tr><tr><td>Coins</td><td>200</td></tr><tr><td>Construction</td><td>4 h</td></tr><tr><td>Ingrédients</td><td>Wood ×50, Stone ×20, Gold ×5</td></tr></tbody></table></div><div class="building-card" id="fish-market"><h3 id="fish-market" tabindex="-1"><img class="building-hero" src="'+c+'" alt="Fish Market"> Fish Market <a class="header-anchor" href="#fish-market" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/fish-market.png&quot; alt=&quot;Fish Market&quot; /&gt; Fish Market&quot;">​</a></h3><p>Transformer / traiter le poisson. Voir <a href="/sunflowerland-wiki/fr/fishing/">Pêche</a>.</p><p><strong>Skin</strong> : change selon la <strong>saison</strong>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>10</td></tr><tr><td>Coins</td><td>0</td></tr><tr><td>Construction</td><td>1 h</td></tr><tr><td>Ingrédients</td><td>Wood ×50, Iron ×10, Gold ×5</td></tr></tbody></table></div><div class="building-card" id="deli"><h3 id="deli" tabindex="-1"><img class="building-hero" src="'+m+'" alt="Deli"> Deli <a class="header-anchor" href="#deli" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/deli.png&quot; alt=&quot;Deli&quot; /&gt; Deli&quot;">​</a></h3><p>Cuisine avancée (plats élaborés).</p><p><strong>Skin</strong> : change selon la <strong>saison</strong>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>16</td></tr><tr><td>Coins</td><td>300</td></tr><tr><td>Construction</td><td>12 h</td></tr><tr><td>Ingrédients</td><td>Wood ×50, Stone ×50, Gold ×10</td></tr></tbody></table></div><div class="building-card" id="warehouse"><h3 id="warehouse" tabindex="-1"><img class="building-hero" src="'+b+'" alt="Warehouse"> Warehouse <a class="header-anchor" href="#warehouse" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/warehouse.png&quot; alt=&quot;Warehouse&quot; /&gt; Warehouse&quot;">​</a></h3><p>Augmente les <strong>stocks de graines</strong> au marché Betty et les <strong>limites d’inventaire</strong> de graines.</p><p><strong>Effet</strong> (bâtiment placé et prêt) :</p><ul><li><strong>+20 %</strong> de stock de graines au marché (chaque type de graine × 1,2, arrondi au supérieur)</li><li>Les <strong>limites d’inventaire</strong> de graines sont calculées à partir de ce stock (donc elles montent aussi d’environ 20 %)</li><li>Ne change pas les outils ni les autres objets — <strong>uniquement les graines</strong></li></ul><p><strong>Skin</strong> : change selon la <strong>saison</strong>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>20</td></tr><tr><td>Coins</td><td>0</td></tr><tr><td>Construction</td><td>2 h</td></tr><tr><td>Ingrédients</td><td>Wood ×250, Stone ×150, Potato ×5000, Pumpkin ×2000, Wheat ×500, Kale ×100</td></tr></tbody></table></div><div class="building-card" id="aging-shed"><h3 id="aging-shed" tabindex="-1"><img class="building-hero" src="'+p+'" alt="Aging Shed"> Aging Shed <a class="header-anchor" href="#aging-shed" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/aging-shed.png&quot; alt=&quot;Aging Shed&quot; /&gt; Aging Shed&quot;">​</a></h3><p>Atelier pour <strong>vieillir</strong>, <strong>fermenter</strong> et préparer des <strong>épices</strong> (aging rack, fermentation rack, spice rack) — produits raffinés à partir de ressources / poissons / pickles, <strong>pas</strong> un simple « vieillissement de fromage ».</p><p><strong>6 niveaux</strong> : chaque niveau ajoute <strong>+1 slot</strong> sur les trois racks (max <strong>6</strong> slots chacun).</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau pour craft</td><td>—</td></tr><tr><td>Coins (craft)</td><td>200</td></tr><tr><td>Construction</td><td>Instantané</td></tr><tr><td>Ingrédients (craft)</td><td>Wood ×30</td></tr></tbody></table><h4 id="upgrades-2" tabindex="-1">Upgrades <a class="header-anchor" href="#upgrades-2" aria-label="Permalink to &quot;Upgrades&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:right;">Niveau</th><th style="text-align:right;">Coût coins</th><th>Ingrédients</th><th style="text-align:right;">Slots (aging / fermentation / spice)</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:right;">200 (craft)</td><td>Wood ×30</td><td style="text-align:right;">1</td></tr><tr><td style="text-align:right;">2</td><td style="text-align:right;">3 000</td><td>Stone ×100, Gold ×20</td><td style="text-align:right;">2</td></tr><tr><td style="text-align:right;">3</td><td style="text-align:right;">4 000</td><td>Wood ×500, Stone ×500</td><td style="text-align:right;">3</td></tr><tr><td style="text-align:right;">4</td><td style="text-align:right;">10 000</td><td>Gold ×100</td><td style="text-align:right;">4</td></tr><tr><td style="text-align:right;">5</td><td style="text-align:right;">20 000</td><td>Crimstone ×10</td><td style="text-align:right;">5</td></tr><tr><td style="text-align:right;">6</td><td style="text-align:right;">100 000</td><td>—</td><td style="text-align:right;">6</td></tr></tbody></table></div><div class="building-card" id="smoothie-shack"><h3 id="smoothie-shack" tabindex="-1"><img class="building-hero" src="'+q+'" alt="Smoothie Shack"> Smoothie Shack <a class="header-anchor" href="#smoothie-shack" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/smoothie-shack.png&quot; alt=&quot;Smoothie Shack&quot; /&gt; Smoothie Shack&quot;">​</a></h3><p>Préparer des <strong>smoothies</strong> / boissons.</p><p><strong>Skin</strong> : change selon l’<strong>île</strong>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>23</td></tr><tr><td>Coins</td><td>0</td></tr><tr><td>Construction</td><td>12 h</td></tr><tr><td>Ingrédients</td><td>Wood ×25, Stone ×25, Iron ×10</td></tr></tbody></table></div><div class="building-card" id="toolshed"><h3 id="toolshed" tabindex="-1"><img class="building-hero" src="'+x+'" alt="Toolshed"> Toolshed <a class="header-anchor" href="#toolshed" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/toolshed.png&quot; alt=&quot;Toolshed&quot; /&gt; Toolshed&quot;">​</a></h3><p>Augmente les stocks / efficacité liés aux <strong>outils</strong>.</p><p><strong>Skin</strong> : change selon la <strong>saison</strong>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>25</td></tr><tr><td>Coins</td><td>0</td></tr><tr><td>Construction</td><td>2 h</td></tr><tr><td>Ingrédients</td><td>Wood ×500, Iron ×30, Gold ×25, Axe ×100, Pickaxe ×50</td></tr></tbody></table></div><div class="building-card" id="barn"><h3 id="barn" tabindex="-1"><img class="building-hero" src="'+f+'" alt="Barn"> Barn <a class="header-anchor" href="#barn" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/barn.png&quot; alt=&quot;Barn&quot; /&gt; Barn&quot;">​</a></h3><p>Élever <strong>vaches</strong> et <strong>moutons</strong>. Voir <a href="/sunflowerland-wiki/fr/animals/">Animaux</a>. <strong>3 niveaux</strong>.</p><p><strong>Skin</strong> : change selon l’<strong>île</strong> / biome, la <strong>saison</strong> et le <strong>niveau</strong>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau pour craft</td><td>30</td></tr><tr><td>Coins (craft)</td><td>200</td></tr><tr><td>Construction</td><td>2 h</td></tr><tr><td>Ingrédients (craft)</td><td>Wood ×150, Iron ×10, Gold ×10</td></tr></tbody></table><h4 id="upgrades-3" tabindex="-1">Upgrades <a class="header-anchor" href="#upgrades-3" aria-label="Permalink to &quot;Upgrades&quot;">​</a></h4><p>Capacité de base : <strong>10 + 5 × (niveau − 1)</strong> animaux. Avec <strong>Barn Blueprint</strong> : +5 animaux <strong>par niveau</strong> de la Barn.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Niveau</th><th style="text-align:right;">Coût coins</th><th>Ingrédients</th><th style="text-align:right;">Animaux (base)</th><th style="text-align:right;">Animaux (+ Barn Blueprint)</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:right;">— (base)</td><td>—</td><td style="text-align:right;">10</td><td style="text-align:right;">15</td></tr><tr><td style="text-align:right;">2</td><td style="text-align:right;">10 000</td><td>Wood ×1000, Iron ×100, Gold ×75, Crimstone ×30</td><td style="text-align:right;">15</td><td style="text-align:right;">25</td></tr><tr><td style="text-align:right;">3</td><td style="text-align:right;">75 000</td><td>Wood ×5000, Iron ×300, Gold ×200, Crimstone ×125, Oil ×250</td><td style="text-align:right;">20</td><td style="text-align:right;">35</td></tr></tbody></table></div><div class="building-card" id="crop-machine"><h3 id="crop-machine" tabindex="-1"><img class="building-hero" src="'+y+'" alt="Crop Machine"> Crop Machine <a class="header-anchor" href="#crop-machine" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/crop-machine.png&quot; alt=&quot;Crop Machine&quot; /&gt; Crop Machine&quot;">​</a></h3><p>Machine à cultures automatique. <strong>Île Desert</strong> requise.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>35</td></tr><tr><td>Coins</td><td>8000</td></tr><tr><td>Construction</td><td>2 h</td></tr><tr><td>Île</td><td>Desert</td></tr><tr><td>Ingrédients</td><td>Wood ×1250, Iron ×125, Crimstone ×50</td></tr></tbody></table></div><div class="building-card" id="greenhouse"><h3 id="greenhouse" tabindex="-1"><img class="building-hero" src="'+v+'" alt="Greenhouse"> Greenhouse <a class="header-anchor" href="#greenhouse" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/greenhouse.png&quot; alt=&quot;Greenhouse&quot; /&gt; Greenhouse&quot;">​</a></h3><p>Cultiver riz, olives, etc. Voir <a href="/sunflowerland-wiki/fr/greenhouse/">Serre</a>. <strong>Île Desert</strong> requise.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau</td><td>46</td></tr><tr><td>Coins</td><td>4800</td></tr><tr><td>Construction</td><td>4 h</td></tr><tr><td>Île</td><td>Desert</td></tr><tr><td>Ingrédients</td><td>Wood ×500, Stone ×100, Crimstone ×25, Oil ×100</td></tr></tbody></table></div><div class="building-card" id="pet-house"><h3 id="pet-house" tabindex="-1"><img class="building-hero" src="'+k+'" alt="Pet House"> Pet House <a class="header-anchor" href="#pet-house" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/pet-house.png&quot; alt=&quot;Pet House&quot; /&gt; Pet House&quot;">​</a></h3><p>Gérer les <strong>animaux de compagnie</strong> (pets). <strong>3 niveaux</strong> — chaque upgrade augmente la capacité.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Niveau pour craft</td><td>—</td></tr><tr><td>Coins (craft)</td><td>5 000</td></tr><tr><td>Construction</td><td>2 h</td></tr><tr><td>Ingrédients (craft)</td><td>Wood ×200, Stone ×100</td></tr></tbody></table><h4 id="upgrades-4" tabindex="-1">Upgrades <a class="header-anchor" href="#upgrades-4" aria-label="Permalink to &quot;Upgrades&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:right;">Niveau</th><th style="text-align:right;">Coût coins</th><th>Ingrédients</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:right;">5 000 (craft)</td><td>Wood ×200, Stone ×100</td></tr><tr><td style="text-align:right;">2</td><td style="text-align:right;">0</td><td>Chewed Bone ×1, Ribbon ×1, Ruffroot ×1, Wild Grass ×1, Heart leaf ×1, Frost Pebble ×1, Dewberry ×1, Acorn ×10, Wood ×250</td></tr><tr><td style="text-align:right;">3</td><td style="text-align:right;">0</td><td>Chewed Bone ×5, Ribbon ×5, Ruffroot ×5, Wild Grass ×5, Heart leaf ×5, Frost Pebble ×5, Dewberry ×5, Moonfur ×10, Acorn ×25, Stone ×200</td></tr></tbody></table></div><h2 id="habitations" tabindex="-1">Habitations <a class="header-anchor" href="#habitations" aria-label="Permalink to &quot;Habitations&quot;">​</a></h2><div class="building-card" id="town-center"><h3 id="town-center" tabindex="-1"><img class="building-hero" src="'+C+'" alt="Town Center"> Town Center <a class="header-anchor" href="#town-center" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/town-center.png&quot; alt=&quot;Town Center&quot; /&gt; Town Center&quot;">​</a></h3><p><strong>Habitation de départ</strong> sur l’île Basic. <strong>Non craftable</strong> — déjà sur la ferme. Remplacé par <strong>House</strong> à l’upgrade vers Spring (Petal Paradise).</p><div class="tip custom-block"><p class="custom-block-title">Astuce place</p><p>Ouvrez la maison et placez vos <strong>boosts</strong> (sauf boosts de zone) <strong>à l’intérieur</strong> pour gagner de la place sur l’île. Valable pour Town Center, House, Manor et Mansion.</p></div><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Craft</td><td>Non (progression d’île)</td></tr><tr><td>Coins</td><td>—</td></tr><tr><td>Construction</td><td>—</td></tr><tr><td>Ingrédients</td><td>—</td></tr></tbody></table></div><div class="building-card" id="house"><h3 id="house" tabindex="-1"><img class="building-hero" src="'+w+'" alt="House"> House <a class="header-anchor" href="#house" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/house.png&quot; alt=&quot;House&quot; /&gt; House&quot;">​</a></h3><p><strong>Habitation principale</strong> sur l’île <strong>Spring</strong> (Petal Paradise). <strong>Non craftable</strong>.</p><p>Fournie automatiquement à l’upgrade d’île (remplace le <strong>Town Center</strong>). Remplacée plus tard par le <strong>Manor</strong> (Desert).</p><p><strong>Skin</strong> : varie aussi selon la <strong>saison</strong>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Craft</td><td>Non (progression d’île → Spring)</td></tr><tr><td>Coins</td><td>—</td></tr><tr><td>Construction</td><td>—</td></tr><tr><td>Ingrédients</td><td>—</td></tr></tbody></table></div><div class="building-card" id="manor"><h3 id="manor" tabindex="-1"><img class="building-hero" src="'+P+'" alt="Manor"> Manor <a class="header-anchor" href="#manor" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/manor.png&quot; alt=&quot;Manor&quot; /&gt; Manor&quot;">​</a></h3><p><strong>Habitation principale</strong> sur l’île <strong>Desert</strong>. <strong>Non craftable</strong>.</p><p>Fournie à l’upgrade d’île (remplace <strong>House</strong>). Remplacée plus tard par le <strong>Mansion</strong> (Volcano et au-delà).</p><p><strong>Skin</strong> : varie aussi selon la <strong>saison</strong>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Craft</td><td>Non (progression d’île → Desert)</td></tr><tr><td>Coins</td><td>—</td></tr><tr><td>Construction</td><td>—</td></tr><tr><td>Ingrédients</td><td>—</td></tr></tbody></table></div><div class="building-card" id="mansion"><h3 id="mansion" tabindex="-1"><img class="building-hero" src="'+_+'" alt="Mansion"> Mansion <a class="header-anchor" href="#mansion" aria-label="Permalink to &quot;&lt;img class=&quot;building-hero&quot; src=&quot;/icons/mansion.png&quot; alt=&quot;Mansion&quot; /&gt; Mansion&quot;">​</a></h3><p><strong>Habitation principale</strong> à partir de l’île <strong>Volcano</strong> (et biomes d’ascension suivants). <strong>Non craftable</strong>.</p><p>Fournie à l’upgrade d’île (remplace <strong>Manor</strong>).</p><p><strong>Skin</strong> : varie aussi selon la <strong>saison</strong>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Craft</td><td>Non (progression d’île → Volcano+)</td></tr><tr><td>Coins</td><td>—</td></tr><tr><td>Construction</td><td>—</td></tr><tr><td>Ingrédients</td><td>—</td></tr></tbody></table></div>',44)])])}const $=H(z,[["render",G]]);export{K as __pageData,$ as default};
